{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 4, "block_type": "paragraph", "section_path": ["Administration Element", "Goal ADM-1."], "text": "The City of Coral Gables Comprehensive Plan and Comprehensive Plan Map, hereinafter referenced as “The Comprehensive Plan”, shall provide a visionary blueprint for the City’s growth, development, and function while preserving its historic and cultural character in concert with the City of Coral Gables City Commission mission and vision.", "extra": {"style": "Body Text"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 5, "block_type": "heading", "section_path": ["Administration Element", "Goal ADM-1.", "Objective ADM-1.1."], "text": "Objective ADM-1.1.", "extra": {"heading_level": 4, "style": "Heading 4"}}
