{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 15, "block_type": "heading", "section_path": ["Administration Element", "Goal ADM-1.", "Objective ADM-1.1.", "Policy ADM-1.1.2.", "Policy ADM-1.1.6."], "text": "Policy ADM-1.1.6.", "extra": {"heading_level": 5, "style": "Heading 5"}}
