{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 17, "block_type": "heading", "section_path": ["Administration Element", "Goal ADM-1.", "Objective ADM-1.1.", "Policy ADM-1.1.2.", "Policy ADM-1.1.7."], "text": "Policy ADM-1.1.7.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 18, "block_type": "paragraph", "section_path": ["Administration Element", "Goal ADM-1.", "Objective ADM-1.1.", "Policy ADM-1.1.2.", "Policy ADM-1.1.7."], "text": "Provide for notice, advertisement, publication, dissemination, and distribution of the Comprehensive Plan and associated amendments to the public and interested parties. All avenues of electronic mediums shall be utilized to apprise all parties of the Comprehensive Plan and future changes.", "extra": {"style": "Body Text"}}
