{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 20, "block_type": "paragraph", "section_path": ["Administration Element", "Goal ADM-1.", "Objective ADM-1.1.", "Objective ADM-1.2."], "text": "Interpret the Comprehensive Plan in a manner that is founded on sound legal and planning principles, and is in accordance with federal, state, and local laws and regulations.", "extra": {"style": "Body Text"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 21, "block_type": "heading", "section_path": ["Administration Element", "Goal ADM-1.", "Objective ADM-1.1.", "Objective ADM-1.2.", "Policy ADM-1.2.1."], "text": "Policy ADM-1.2.1.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 22, "block_type": "paragraph", "section_path": ["Administration Element", "Goal ADM-1.", "Objective ADM-1.1.", "Objective ADM-1.2.", "Policy ADM-1.2.1."], "text": "The Comprehensive Plan supports and solidifies the implementation of the City’s land development regulations which includes the City Zoning Code and Zoning Map(s). The Comprehensive Plan shall also support the City Charter and City Code.", "extra": {"style": "Body Text"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 23, "block_type": "heading", "section_path": ["Administration Element", "Goal ADM-1.", "Objective ADM-1.1.", "Objective ADM-1.2.", "Policy ADM-1.2.2."], "text": "Policy ADM-1.2.2.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 24, "block_type": "paragraph", "section_path": ["Administration Element", "Goal ADM-1.", "Objective ADM-1.1.", "Objective ADM-1.2.", "Policy ADM-1.2.2."], "text": "Designate a primary Development Review Official (DRO) to interpret the Comprehensive Plan.", "extra": {"style": "Body Text"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 25, "block_type": "heading", "section_path": ["Administration Element", "Goal ADM-1.", "Objective ADM-1.1.", "Objective ADM-1.3."], "text": "Objective ADM-1.3.", "extra": {"heading_level": 4, "style": "Heading 4"}}
