{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 222, "block_type": "heading", "section_path": ["Administration Element", "Future Land Use Element", "Goal FLU-2.", "Objective FLU-2.1."], "text": "Objective FLU-2.1.", "extra": {"heading_level": 4, "style": "Heading 4"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 223, "block_type": "paragraph", "section_path": ["Administration Element", "Future Land Use Element", "Goal FLU-2.", "Objective FLU-2.1."], "text": "The City shall develop, maintain, and implement land development regulations that serve to regulate the form, function, and interplay of land use, development, and associated activities, further the City’s Comprehensive Plan, and are consistent and compatible with County, State, and Federal plans and regulations.", "extra": {"style": "Body Text"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 224, "block_type": "heading", "section_path": ["Administration Element", "Future Land Use Element", "Goal FLU-3."], "text": "Goal FLU-3.", "extra": {"heading_level": 3, "style": "Heading 3"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 225, "block_type": "paragraph", "section_path": ["Administration Element", "Future Land Use Element", "Goal FLU-3."], "text": "The City as a part of its development review process shall engage public/community participation and collaboration to provide for a transparent development review process.", "extra": {"style": "Body Text"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 226, "block_type": "heading", "section_path": ["Administration Element", "Future Land Use Element", "Goal FLU-3.", "Objective FLU-3.1."], "text": "Objective FLU-3.1.", "extra": {"heading_level": 4, "style": "Heading 4"}}
