{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 240, "block_type": "heading", "section_path": ["Administration Element", "Future Land Use Element", "Goal FLU-3.", "Objective FLU-3.3.", "Policy FLU-3.3.2."], "text": "Policy FLU-3.3.2.", "extra": {"heading_level": 5, "style": "Heading 5"}}
