{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 480, "block_type": "heading", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-3.", "Objective COM-3.1.", "Policy COM-3.1.2."], "text": "Policy COM-3.1.2.", "extra": {"heading_level": 5, "style": "Heading 5"}}
