{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 482, "block_type": "paragraph", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-3.", "Objective COM-3.1.", "Policy COM-3.1.2."], "text": "Residential pickup is to be twice a week for household waste; once per week for trash; and once per week for recycling.", "extra": {"style": "Body Text"}}
