{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 485, "block_type": "paragraph", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-3.", "Objective COM-3.1.", "Policy COM-3.1.3."], "text": "In cooperation with Miami-Dade County, the City shall provide and maintain a minimum acceptable LOS for solid waste collection at an annual average design generation rate of:", "extra": {"style": "Body Text"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 486, "block_type": "paragraph", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-3.", "Objective COM-3.1.", "Policy COM-3.1.3."], "text": "Five pounds (5 lbs) per capita per day for residential garbage and trash; One half pound (0.5 lbs) per capita per day for residential recycling; and", "extra": {"style": "Body Text"}}
