{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 498, "block_type": "heading", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-4.", "Objective COM-4.1."], "text": "Objective COM-4.1.", "extra": {"heading_level": 4, "style": "Heading 4"}}
