{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 503, "block_type": "paragraph", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-4.", "Objective COM-4.1.", "Policy COM-4.1.2."], "text": "Water conservation, natural resource conservation and related policies will be supported by inclusion in positive drain systems of pollution control facilities which will separate oils and greases as well as sediment and grit from the discharge waters, as resources permit.", "extra": {"style": "Body Text"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 504, "block_type": "heading", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-4.", "Objective COM-4.1.", "Policy COM-4.1.3."], "text": "Policy COM-4.1.3.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 505, "block_type": "paragraph", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-4.", "Objective COM-4.1.", "Policy COM-4.1.3."], "text": "Issue development orders only to projects that meet or exceed the minimum acceptable LOS standards for drainage and flood protection as reviewed through the City’s Concurrency Management Program.", "extra": {"style": "Body Text"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 506, "block_type": "heading", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-4.", "Objective COM-4.1.", "Policy COM-4.1.4."], "text": "Policy COM-4.1.4.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 507, "block_type": "paragraph", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-4.", "Objective COM-4.1.", "Policy COM-4.1.4."], "text": "Assist property owners with general information related to flood zone per Federal Emergency Management Agency (FEMA) maps and available floodproofing technology. Flood prone areas which represent substantial risk for occupants during disaster events should be considered for corrective action or targeted for special attention during disaster response actions.", "extra": {"style": "Body Text"}}
