{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 508, "block_type": "heading", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-4.", "Objective COM-4.1.", "Policy COM-4.1.5."], "text": "Policy COM-4.1.5.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 509, "block_type": "paragraph", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-4.", "Objective COM-4.1.", "Policy COM-4.1.5."], "text": "The minimum acceptable Flood Protection LOS standards for the City shall be protection from the degree of flooding that would result for a duration of one day from a ten-year storm. All structures shall be constructed at, or above, the minimum floor elevation specified in the Flood Insurance Rate Maps for Coral Gables in Miami-Dade County, Florida. All new development must retain at least the first one inch (1\") of storm water runoff onsite, or other nonpublic sites as may be secured for permanent services. Designs to meet this first inch criteria will be reviewed for design solutions to meet actual site conditions. The burden for the construction of such facilities shall be borne by the developer and/or owner of such sites. Failure of such facilities and subsequent corrections shall also be the responsibility of the developer and/or owner. The City may require greater than the first one inch onsite retention where the City establishes more restrictive rules in the public interest.", "extra": {"style": "Body Text"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 510, "block_type": "heading", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-4.", "Objective COM-4.1.", "Policy COM-4.1.6."], "text": "Policy COM-4.1.6.", "extra": {"heading_level": 5, "style": "Heading 5"}}
