{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 513, "block_type": "heading", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-5."], "text": "Goal COM-5.", "extra": {"heading_level": 3, "style": "Heading 3"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 514, "block_type": "paragraph", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-5."], "text": "The City of Coral Gables shall ensure that a safe potable water supply with sufficient quantity and quality to serve the City is available.", "extra": {"style": "Body Text"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 515, "block_type": "heading", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-5.", "Objective COM-5.1."], "text": "Objective COM-5.1.", "extra": {"heading_level": 4, "style": "Heading 4"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 516, "block_type": "paragraph", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-5.", "Objective COM-5.1."], "text": "The potable water treatment and distribution system shall be maintained by the system owner and operators in a safe, effective, efficient, environmentally sound and reliable manner consistent with this Comprehensive Plan.", "extra": {"style": "Body Text"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 517, "block_type": "heading", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-5.", "Objective COM-5.1.", "Policy COM-5.1.1."], "text": "Policy COM-5.1.1.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 518, "block_type": "paragraph", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-5.", "Objective COM-5.1.", "Policy COM-5.1.1."], "text": "The minimum acceptable LOS standards of potable water shall be 155 gallons per day per capita and such water is to be delivered to users at a pressure of not less than twenty pounds per square inch (psi) and not greater than one-hundred (100) psi.

", "Policy COM-5.1.1."], "text": "Policy COM-5.1.1.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 518, "block_type": "paragraph", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-5.", "Objective COM-5.1.", "Policy COM-5.1.1."], "text": "The minimum acceptable LOS standards of potable water shall be 155 gallons per day per capita and such water is to be delivered to users at a pressure of not less than twenty pounds per square inch (psi) and not greater than one-hundred (100) psi. The regional treatment system shall operate with a maximum daily rated capacity which is no less than two (2%) percent above the maximum day daily flow for the preceding year and an annual average daily capacity two (2%) percent above the average daily system demand for the preceding 5 years. Water quality shall meet or exceed all federal, state, and County primary standards for potable water; and system wide storage capacity for finished water shall equal no less than fifteen (15%) percent of the Countywide average daily demand.", "extra": {"style": "Body Text"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 519, "block_type": "heading", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-5.", "Objective COM-5.1.", "Policy COM-5.1.2."], "text": "Policy COM-5.1.2.", "extra": {"heading_level": 5, "style": "Heading 5"}}
