{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 657, "block_type": "heading", "section_path": ["Administration Element", "Housing Element", "Goal HOU-1.", "Objective HOU-1.7."], "text": "Objective HOU-1.7.", "extra": {"heading_level": 4, "style": "Heading 4"}}
