{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 670, "block_type": "heading", "section_path": ["Administration Element", "Education Element", "Goal EDU-1."], "text": "Goal EDU-1.", "extra": {"heading_level": 3, "style": "Heading 3"}}
