{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 672, "block_type": "heading", "section_path": ["Administration Element", "Education Element", "Goal EDU-1.", "Objective EDU-1.1."], "text": "Objective EDU-1.1.", "extra": {"heading_level": 4, "style": "Heading 4"}}
