{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 685, "block_type": "paragraph", "section_path": ["Administration Element", "Education Element", "Goal EDU-1.", "Objective EDU-1.1.", "Policy EDU-1.1.6."], "text": "Miami-Dade County Public Schools’ comments shall be sought and considered on Comprehensive Plan and Change in Zoning classifications which provide for an increase in residential density which could impact the school district, to be consistent with the terms of the state mandated Interlocal Agreement pursuant to Sections 1013.33 and 163.31777, Florida Statutes.", "extra": {"style": "Body Text"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 686, "block_type": "heading", "section_path": ["Administration Element", "Education Element", "Goal EDU-1.", "Objective EDU-1.1.", "Policy EDU-1.1.7."], "text": "Policy EDU-1.1.7.", "extra": {"heading_level": 5, "style": "Heading 5"}}
