{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 866, "block_type": "heading", "section_path": ["Administration Element", "Mobility Element", "Goal MOB-2.", "Objective MOB-2.2.", "Policy MOB-2.2.4."], "text": "Policy MOB-2.2.4.", "extra": {"heading_level": 5, "style": "Heading 5"}}
