{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 990, "block_type": "paragraph", "section_path": ["Administration Element", "Natural Resources Element", "Goal NAT-1.", "Objective NAT-1.2.", "Policy NAT-1.2.7."], "text": "The potable water network is an interconnected, countywide system, therefore, the City will cooperate with MDWASD to jointly develop methodologies and procedures for biannually updating estimates of system demand and capacity, and ensure that sufficient capacity to serve development exists. The City will prepare and submit a Water Conservation Plan to the County at the same time as the City submits the updated 5-Year Water Supply Facilities Work Plan.", "extra": {"style": "Body Text"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 991, "block_type": "heading", "section_path": ["Administration Element", "Natural Resources Element", "Goal NAT-1.", "Objective NAT-1.2.", "Policy NAT-1.2.8."], "text": "Policy NAT-1.2.8.", "extra": {"heading_level": 5, "style": "Heading 5"}}
