{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1102, "block_type": "heading", "section_path": ["Administration Element", "Recreation and Open Space Element", "Goal REC-1."], "text": "Goal REC-1.", "extra": {"heading_level": 3, "style": "Heading 3"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1103, "block_type": "paragraph", "section_path": ["Administration Element", "Recreation and Open Space Element", "Goal REC-1."], "text": "The City of Coral Gables recreation system will serve the residents with neighborhood parks and open spaces that offer both passive and active recreation activities and facilities; that are linked together with a network of sidewalks, pathways and bike lanes; and provide public/open spaces that serve as gathering places in the downtown area.", "extra": {"style": "Body Text"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1104, "block_type": "heading", "section_path": ["Administration Element", "Recreation and Open Space Element", "Goal REC-1.", "Objective REC-1.1."], "text": "Objective REC-1.1.", "extra": {"heading_level": 4, "style": "Heading 4"}}
