{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1106, "block_type": "heading", "section_path": ["Administration Element", "Recreation and Open Space Element", "Goal REC-1.", "Objective REC-1.1.", "Policy REC-1.1.1."], "text": "Policy REC-1.1.1.", "extra": {"heading_level": 5, "style": "Heading 5"}}
