{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1191, "block_type": "heading", "section_path": ["Administration Element", "Historical Resources Element", "Goal HIS-1.", "Objective HIS-1.1.", "Policy HIS-1.1.1."], "text": "Policy HIS-1.1.1.", "extra": {"heading_level": 5, "style": "Heading 5"}}
