{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1315, "block_type": "heading", "section_path": ["Administration Element", "Public Safety Element", "Goal SAF-2.", "Objective SAF-2.2.", "Policy SAF-2.2.1."], "text": "Policy SAF-2.2.1.", "extra": {"heading_level": 5, "style": "Heading 5"}}
