{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1380, "block_type": "paragraph", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.2.", "Policy CIE-1.2.1."], "text": "Traffic Circulation LOS. The minimum or lowest quality acceptable peakperiod* operating LOS standards for State Principal Arterial, Minor Arterial, County Minor Arterial, County and City Collector roads within the City shall be the minimum acceptable peakperiod LOS standard:", "extra": {"style": "Body Text"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1381, "block_type": "paragraph", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.2.", "Policy CIE-1.2.1."], "text": "Where public transit service does not exist, roadways shall operate at or above LOS E; within the Special Transportation Area (STA) twenty (20%) percent of nonState roads may operate below LOS E.", "extra": {"style": "Body Text"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1382, "block_type": "paragraph", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.2.", "Policy CIE-1.2.1."], "text": "Where public transit service having headways of twenty (20) minutes or less is provided within 1/2 mile distance, roadways shall operate at no greater than one-hundred twenty (120%) percent of their capacity.", "extra": {"style": "Body Text"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1383, "block_type": "paragraph", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.2.", "Policy CIE-1.2.1."], "text": "Where commuter rail or express bus public transit service exists, generally parallel roads within 1/2 mile shall operate at no greater than one-hundred fifty (150%) percent of their capacity.", "extra": {"style": "Body Text"}}
