{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1385, "block_type": "paragraph", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.2.", "Policy CIE-1.2.1."], "text": "Sanitary Sewer LOS. Existing sanitary sewer systems within the jurisdiction of the City shall be operated at a LOS not less restrictive than that provided for in the Miami-Dade County Comprehensive Master Plan, as amended. All sanitary sewer systems within the jurisdiction of the City shall be operated to provide at least the minimum LOS as described herein:", "extra": {"style": "Body Text"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1386, "block_type": "paragraph", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.2.", "Policy CIE-1.2.1."], "text": "The Miami-Dade County regional wastewater treatment and disposal system shall operate with a design capacity of two (2) above average daily flow for the preceding year.", "extra": {"style": "Body Text"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1387, "block_type": "paragraph", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.2.", "Policy CIE-1.2.1."], "text": "Effluent discharged from Miami-Dade County wastewater treatment plants shall meet all federal, State, and County standards.", "extra": {"style": "Body Text"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1388, "block_type": "paragraph", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.2.", "Policy CIE-1.2.1."], "text": "The local system shall maintain the design capacity to collect and dispose of one-hundred thirty-five (135) gallons of sewage per capita, per day.", "extra": {"style": "Body Text"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1389, "block_type": "paragraph", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.2.", "Policy CIE-1.2.1."], "text": "All collection and treatment facilities shall maintain the capacity to transport and treat peak demand flow without overflow.

