{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1431, "block_type": "paragraph", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.3.", "Policy CIE-1.3.3."], "text": "The necessary facilities are funded and programmed for implementation in the CIE for construction within the first three years of the City’s adopted capital budget, or similarly adopted budget of other government agencies; or", "extra": {"style": "Body Text"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1432, "block_type": "paragraph", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.3.", "Policy CIE-1.3.3."], "text": "The necessary facilities and services are guaranteed, in an enforceable development agreement, to be provided by the developer. An enforceable development agreement may include, but is not limited to, development agreements pursuant to Section 163.3220, Florida Statutes or an agreement or development order issued pursuant to Chapter 380, Florida Statutes; or", "extra": {"style": "Body Text"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1433, "block_type": "paragraph", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.3.", "Policy CIE-1.3.3."], "text": "Timely provision of the necessary facilities will be guaranteed by some other means or instrument providing substantially equivalent assurances.", "extra": {"style": "Body Text"}}
