{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1436, "block_type": "paragraph", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.3.", "Policy CIE-1.3.3."], "text": "The development order includes the condition that at the time of the issuance of a certificate of occupancy or its functional equivalent, the acreage for the necessary facilities and services to serve the new development are dedicated or acquired by the City, or funds in the amount of the developer’s fair share are committed; and", "extra": {"style": "Body Text"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1437, "block_type": "paragraph", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.3.", "Policy CIE-1.3.3."], "text": "The development order includes the conditions that the necessary facilities and services needed to serve the new development are scheduled to be in place or under actual construction not more than one year after issuance of a certificate of occupancy or its functional equivalent as provided in the adopted 5-Year Schedule of Capital Improvements; or", "extra": {"style": "Body Text"}}
