{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1442, "block_type": "paragraph", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.3.", "Policy CIE-1.3.3."], "text": "A development order or permit is issued subject to the conditions that the necessary facilities and services needed to serve the new development are scheduled to be in place or under actual construction not more than three years after issuance of a certificate of occupancy or its functional equivalent as provided in the City’s adopted 5-Year Schedule of Capital Improvements or transportation projects included in the first three years of the applicable, adopted Florida Department of Transportation Five Year Work Program and Miami-Dade County’s 5-Year Transportation Improvement Program.", "extra": {"style": "Body Text"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1443, "block_type": "paragraph", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.3.", "Policy CIE-1.3.3."], "text": "The estimated date of commencement of actual construction and the estimated date of project completion must be included.", "extra": {"style": "Body Text"}}
