{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1458, "block_type": "paragraph", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.5."], "text": "Protect the public fiscal welfare by limitations on the amount and kind of debt the City may incur.", "extra": {"style": "Body Text"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1459, "block_type": "heading", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.5.", "Policy CIE-1.5.1."], "text": "Policy CIE-1.5.1.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1460, "block_type": "paragraph", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.5.", "Policy CIE-1.5.1."], "text": "The City shall be limited on the use of revenue bonds to no more than twenty-five (25%) percent total debt. The total debt service shall not exceed six (6%) percent of total revenue; and outstanding capital indebtedness shall not exceed eight (8%) percent of the total property tax base of the City.", "extra": {"style": "Body Text"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1461, "block_type": "heading", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.6."], "text": "Objective CIE-1.6.", "extra": {"heading_level": 4, "style": "Heading 4"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1462, "block_type": "paragraph", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.6.

", "Objective CIE-1.6."], "text": "Objective CIE-1.6.", "extra": {"heading_level": 4, "style": "Heading 4"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1462, "block_type": "paragraph", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.6."], "text": "The City shall ensure the provision of public facilities and services at no less than the established LOS standards and manage the land development process to assure public facility needs do not exceed the City's ability to adequately fund and provide or require provision of needed capital improvements. The City will use the collection of impact fees to adequately fund services and projects related to roadways, parks, police, fire and general government services.", "extra": {"style": "Body Text"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1463, "block_type": "heading", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.6.", "Policy CIE-1.6.1."], "text": "Policy CIE-1.6.1.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1464, "block_type": "paragraph", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.6.", "Policy CIE-1.6.1."], "text": "The Concurrency Management Program (CMP) shall provide for the regulation and administration of the issuance of threshold development orders to be predicated upon the provision of public services consistent with this plan.", "extra": {"style": "Body Text"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1465, "block_type": "heading", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.6.", "Policy CIE 1.6.2."], "text": "Policy CIE 1.6.2.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1466, "block_type": "paragraph", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.6.", "Policy CIE 1.6.2."], "text": "The City shall continue its established impact fee system that supports the Comprehensive Plan to ensure that public facilities shall be available to serve new development.", "extra": {"style": "Body Text"}}
