{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1469, "block_type": "heading", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.6.", "Policy CIE-1.6.4."], "text": "Policy CIE-1.6.4.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1470, "block_type": "paragraph", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.6.", "Policy CIE-1.6.4."], "text": "Funds collected through impact fees shall be used to provide additional public facilities and capital improvements to accommodate new development.", "extra": {"style": "Body Text"}}
{"doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "block_index": 1471, "block_type": "heading", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.6.", "Policy CIE-1.6.5."], "text": "Policy CIE-1.6.5.", "extra": {"heading_level": 5, "style": "Heading 5"}}
