{"id": "Coral_Gables_Comprehensive_Plan__b18__c0__93916c104766", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Goal ADM-1.", "Objective ADM-1.1.", "Policy ADM-1.1.2.", "Policy ADM-1.1.7."], "block_type": "paragraph", "block_index": 18, "text": "Provide for notice, advertisement, publication, dissemination, and distribution of the Comprehensive Plan and associated amendments to the public and interested parties. All avenues of electronic mediums shall be utilized to apprise all parties of the Comprehensive Plan and future changes.", "extra": {"style": "Body Text"}}
