{"id": "Coral_Gables_Comprehensive_Plan__b23__c0__3a7aa75c559e", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Goal ADM-1.", "Objective ADM-1.1.", "Objective ADM-1.2.", "Policy ADM-1.2.2."], "block_type": "heading", "block_index": 23, "text": "Policy ADM-1.2.2.", "extra": {"heading_level": 5, "style": "Heading 5"}}
