{"id": "Coral_Gables_Comprehensive_Plan__b31__c0__d819326a9e6f", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Goal ADM-1.", "Objective ADM-1.1.", "Objective ADM-1.3.", "Policy ADM-1.3.3."], "block_type": "heading", "block_index": 31, "text": "Policy ADM-1.3.3.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"id": "Coral_Gables_Comprehensive_Plan__b32__c0__a767de7082c9", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Goal ADM-1.", "Objective ADM-1.1.", "Objective ADM-1.3.", "Policy ADM-1.3.3."], "block_type": "paragraph", "block_index": 32, "text": "Designate a primary Development Review Official (DRO) charged with overseeing amendments to the Comprehensive Plan. The DRO shall possess the requisite comprehensive planning knowledge, experience, and skills to fairly and effectively amend the Comprehensive Plan.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b33__c0__75e6917889d4", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Goal ADM-1.", "Objective ADM-1.1.", "Objective ADM-1.3.", "Policy ADM-1.3.4."], "block_type": "heading", "block_index": 33, "text": "Policy ADM-1.3.4.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"id": "Coral_Gables_Comprehensive_Plan__b34__c0__b12886f5e1a4", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Goal ADM-1.", "Objective ADM-1.1.", "Objective ADM-1.3.", "Policy ADM-1.3.4."], "block_type": "paragraph", "block_index": 34, "text": "Budget and allocate adequate funding for implementation of the Comprehensive Plan. Emphasis shall be placed on funding projects in the Capital Improvements Element and Programs, with particular emphasis on those that are required in order to maintain or attain and exceed adopted Levels of Service (LOS).", "extra": {"style": "Body Text"}}
