{"id": "Coral_Gables_Comprehensive_Plan__b39__c0__c2d377f56a1b", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Goal ADM-1.", "Objective ADM-1.1.", "Objective ADM-1.4.", "Policy ADM-1.4.2."], "block_type": "heading", "block_index": 39, "text": "Policy ADM-1.4.2.", "extra": {"heading_level": 5, "style": "Heading 5"}}
