{"id": "Coral_Gables_Comprehensive_Plan__b410__c0__d72e85ec87dc", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Community Facilities Element"], "block_type": "paragraph", "block_index": 410, "text": "Goals, Objectives and Policies:", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b411__c0__b2b414527dd2", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-1.

"], "block_type": "heading", "block_index": 411, "text": "Goal COM-1.", "extra": {"heading_level": 3, "style": "Heading 3"}}
{"id": "Coral_Gables_Comprehensive_Plan__b412__c0__5d1691851218", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-1."], "block_type": "paragraph", "block_index": 412, "text": "The City shall meet the existing and future public facilities needs of the City’s residents and businesses through the provision of safe and efficient public facilities and services. The City constructs, maintains, and operates public facilities and services in an environmentally sensitive manner that is coordinated with the needs and efforts of other jurisdictions, and is compatible with the City’s Future Land Use Map.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b413__c0__6893dc54b977", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-1.", "Objective COM-1.1."], "block_type": "heading", "block_index": 413, "text": "Objective COM-1.1.", "extra": {"heading_level": 4, "style": "Heading 4"}}
{"id": "Coral_Gables_Comprehensive_Plan__b414__c0__7facc3d59c72", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-1.", "Objective COM-1.1."], "block_type": "paragraph", "block_index": 414, "text": "Maintain and enhance public facilities and delivery of services for both existing and future residents. The City shall allocate resources for the necessary provision, repair, replacement, and/or upgrading of facilities and services necessary to maintain locally adopted Level of Service (LOS) standards.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b415__c0__91b8b073e950", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-1.", "Objective COM-1.1.", "Policy COM-1.1.1."], "block_type": "heading", "block_index": 415, "text": "Policy COM-1.1.1.", "extra": {"heading_level": 5, "style": "Heading 5"}}
