{"id": "Coral_Gables_Comprehensive_Plan__b418__c0__c5dda7e3a88f", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-2."], "block_type": "heading", "block_index": 418, "text": "Goal COM-2.", "extra": {"heading_level": 3, "style": "Heading 3"}}
{"id": "Coral_Gables_Comprehensive_Plan__b419__c0__59febd5ca5cb", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-2."], "block_type": "paragraph", "block_index": 419, "text": "The City will protect the health and safety of the public by ensuring sanitary sewer treatment that meets established quality, is environmentally sound, cost effective and meets the City’s present and future needs.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b420__c0__56ff0d53b1c9", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-2.", "Objective COM-2.1."], "block_type": "heading", "block_index": 420, "text": "Objective COM-2.1.", "extra": {"heading_level": 4, "style": "Heading 4"}}
{"id": "Coral_Gables_Comprehensive_Plan__b421__c0__6ae2dc4ceb64", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-2.", "Objective COM-2.1."], "block_type": "paragraph", "block_index": 421, "text": "Ensure effective septic tank utilization for single-family and duplex land uses where they remain safe, efficient, and environmentally sound and the least costly long term method of disposal of sanitary waste. All other areas are to be efficiently and effectively serviced by sanitary sewer systems as financially feasible. This objective shall be achieved through the implementation of the following policies.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b422__c0__3645306cc152", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-2.", "Objective COM-2.1.", "Policy COM-2.1.1."], "block_type": "heading", "block_index": 422, "text": "Policy COM-2.1.1.

