{"id": "Coral_Gables_Comprehensive_Plan__b422__c0__3645306cc152", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-2.", "Objective COM-2.1.", "Policy COM-2.1.1."], "block_type": "heading", "block_index": 422, "text": "Policy COM-2.1.1.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"id": "Coral_Gables_Comprehensive_Plan__b423__c0__0c626a4ef382", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-2.", "Objective COM-2.1.", "Policy COM-2.1.1."], "block_type": "paragraph", "block_index": 423, "text": "Vacant single-family residential lots can be developed and septic tanks installed provided certain conditions are met. These conditions are:", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b424__c0__3a2c7a9c6532", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-2.", "Objective COM-2.1.", "Policy COM-2.1.1."], "block_type": "paragraph", "block_index": 424, "text": "Sewage loadings of gallons per day per square foot do not exceed those recommended by the septic tank code, for the size drainfield or absorption area that is available.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b425__c0__bbc871d76c0b", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-2.", "Objective COM-2.1.", "Policy COM-2.1.1."], "block_type": "paragraph", "block_index": 425, "text": "Mounded soil absorption fields shall not be permitted.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b426__c0__8a4d27dffe07", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-2.", "Objective COM-2.1.", "Policy COM-2.1.1."], "block_type": "paragraph", "block_index": 426, "text": "Connection to sanitary sewer shall be required upon availability of such service.", "extra": {"style": "Body Text"}}
