{"id": "Coral_Gables_Comprehensive_Plan__b429__c0__8879a8b35719", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-2.", "Objective COM-2.1.", "Policy COM-2.1.1."], "block_type": "paragraph", "block_index": 429, "text": "The lot is not located in a wellfield protection area or where private wells are in use.", "extra": {"style": "Body Text"}}
