{"id": "Coral_Gables_Comprehensive_Plan__b493__c0__413840e0fa01", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-3.", "Objective COM-3.1.", "Policy COM-3.1.6."], "block_type": "heading", "block_index": 493, "text": "Policy COM-3.1.6.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"id": "Coral_Gables_Comprehensive_Plan__b494__c0__9f3e19533b5d", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-3.", "Objective COM-3.1.", "Policy COM-3.1.6."], "block_type": "paragraph", "block_index": 494, "text": "The City shall continue to employ water conservation strategies and techniques to minimize the use of potable water in the provision of solid waste collection services. Such strategies shall include management attention to reducing unattended washdown, self closing nozzles, and wash down schedules based upon need and not just time schedule. The City shall continue using recycling procedures for portions of water usage in its solid waste collection services.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b495__c0__bf2c2f4a930e", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-3.", "Objective COM-3.1.", "Policy COM-3.1.6."], "block_type": "paragraph", "block_index": 495, "text": "Drainage.

