{"id": "Coral_Gables_Comprehensive_Plan__b514__c0__9cab5c927da3", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-5."], "block_type": "paragraph", "block_index": 514, "text": "The City of Coral Gables shall ensure that a safe potable water supply with sufficient quantity and quality to serve the City is available.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b515__c0__deb09f0ddf97", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-5.", "Objective COM-5.1."], "block_type": "heading", "block_index": 515, "text": "Objective COM-5.1.", "extra": {"heading_level": 4, "style": "Heading 4"}}
{"id": "Coral_Gables_Comprehensive_Plan__b516__c0__033715a14e7e", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-5.", "Objective COM-5.1."], "block_type": "paragraph", "block_index": 516, "text": "The potable water treatment and distribution system shall be maintained by the system owner and operators in a safe, effective, efficient, environmentally sound and reliable manner consistent with this Comprehensive Plan.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b517__c0__d203837842d4", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-5.", "Objective COM-5.1.", "Policy COM-5.1.1."], "block_type": "heading", "block_index": 517, "text": "Policy COM-5.1.1.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"id": "Coral_Gables_Comprehensive_Plan__b518__c0__d5f94a6b412b", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Community Facilities Element", "Goal COM-5.", "Objective COM-5.1.", "Policy COM-5.1.1."], "block_type": "paragraph", "block_index": 518, "text": "The minimum acceptable LOS standards of potable water shall be 155 gallons per day per capita and such water is to be delivered to users at a pressure of not less than twenty pounds per square inch (psi) and not greater than one-hundred (100) psi. The regional treatment system shall operate with a maximum daily rated capacity which is no less than two (2%) percent above the maximum day daily flow for the preceding year and an annual average daily capacity two (2%) percent above the average daily system demand for the preceding 5 years. Water quality shall meet or exceed all federal, state, and County primary standards for potable water; and system wide storage capacity for finished water shall equal no less than fifteen (15%) percent of the Countywide average daily demand.

", "Objective COM-5.1.", "Policy COM-5.1.1."], "block_type": "paragraph", "block_index": 518, "text": "The minimum acceptable LOS standards of potable water shall be 155 gallons per day per capita and such water is to be delivered to users at a pressure of not less than twenty pounds per square inch (psi) and not greater than one-hundred (100) psi. The regional treatment system shall operate with a maximum daily rated capacity which is no less than two (2%) percent above the maximum day daily flow for the preceding year and an annual average daily capacity two (2%) percent above the average daily system demand for the preceding 5 years. Water quality shall meet or exceed all federal, state, and County primary standards for potable water; and system wide storage capacity for finished water shall equal no less than fifteen (15%) percent of the Countywide average daily demand.", "extra": {"style": "Body Text"}}
