"], "block_type": "heading", "block_index": 561, "text": "Goal HOU-1.", "extra": {"heading_level": 3, "style": "Heading 3"}}
{"id": "Coral_Gables_Comprehensive_Plan__b562__c0__0c71bff37a06", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Housing Element", "Goal HOU-1."], "block_type": "paragraph", "block_index": 562, "text": "Provide a supply of housing that addresses the City’s needs that shall include a variety of housing opportunities for all income ranges, provide housing diversity to enhance the City’s social and economic growth and continue to be a distinctive, diverse, attractive and desirable place to live.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b563__c0__4d5999d9e992", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Housing Element", "Goal HOU-1.", "Objective HOU-1.1."], "block_type": "heading", "block_index": 563, "text": "Objective HOU-1.1.", "extra": {"heading_level": 4, "style": "Heading 4"}}
{"id": "Coral_Gables_Comprehensive_Plan__b564__c0__51347b3271e2", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Housing Element", "Goal HOU-1.", "Objective HOU-1.1."], "block_type": "paragraph", "block_index": 564, "text": "Provide adequate and affordable housing to satisfy the community needs for existing and future residents.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b565__c0__77e8f42aa487", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Housing Element", "Goal HOU-1.", "Objective HOU-1.1.", "Policy HOU-1.1.1."], "block_type": "heading", "block_index": 565, "text": "Policy HOU-1.1.1.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"id": "Coral_Gables_Comprehensive_Plan__b566__c0__c801b7001524", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Housing Element", "Goal HOU-1.", "Objective HOU-1.1.", "Policy HOU-1.1.1."], "block_type": "paragraph", "block_index": 566, "text": "The City shall support the involvement of county, regional, state, and federal agencies in housing production, including new construction and/or rehabilitation, where appropriate.", "extra": {"style": "Body Text"}}
