{"id": "Coral_Gables_Comprehensive_Plan__b649__c0__6d766daa62e6", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Housing Element", "Goal HOU-1.", "Objective HOU-1.5.", "Policy HOU-1.5.9."], "block_type": "heading", "block_index": 649, "text": "Policy HOU-1.5.9.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"id": "Coral_Gables_Comprehensive_Plan__b650__c0__8c203fbe01c0", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Housing Element", "Goal HOU-1.", "Objective HOU-1.5.", "Policy HOU-1.5.9."], "block_type": "paragraph", "block_index": 650, "text": "The Coral Gables Planning Department shall continue to provide technical assistance, information and housing data to the private sector in order to maintain a housing production capacity sufficient to meet the projected housing market demand and continue to advance fair housing and elimination of discrimination in housing.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b651__c0__157902d450c2", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Housing Element", "Goal HOU-1.", "Objective HOU-1.5.", "Policy HOU-1.5.10."], "block_type": "heading", "block_index": 651, "text": "Policy HOU-1.5.10.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"id": "Coral_Gables_Comprehensive_Plan__b652__c0__9309d066facd", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Housing Element", "Goal HOU-1.", "Objective HOU-1.5.", "Policy HOU-1.5.10."], "block_type": "paragraph", "block_index": 652, "text": "The City shall continue to assist in developing public/private partnership in order to improve the efficiency and expand the capacity of the City’s share of the regions housing needs while recognizing the private sector as the primary provider of housing. Actions shall include coordinating the timing and location of City sanitary sewer facilities and water services in order to promote the timely extension of water and wastewater services to residential areas as necessary. Similarly, the City shall also coordinate the installation of community facilities supportive to housing resources.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b653__c0__c8d378655038", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Housing Element", "Goal HOU-1.", "Objective HOU-1.6."], "block_type": "heading", "block_index": 653, "text": "Objective HOU-1.6.", "extra": {"heading_level": 4, "style": "Heading 4"}}
