{"id": "Coral_Gables_Comprehensive_Plan__b654__c0__ccbced540151", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Housing Element", "Goal HOU-1.", "Objective HOU-1.6."], "block_type": "paragraph", "block_index": 654, "text": "Provide equitable treatment for all residents of Coral Gables displaced through public programs or activities.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b655__c0__c32d0fd05d5c", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Housing Element", "Goal HOU-1.", "Objective HOU-1.6.", "Policy HOU-1.6.1."], "block_type": "heading", "block_index": 655, "text": "Policy HOU-1.6.1.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"id": "Coral_Gables_Comprehensive_Plan__b656__c0__b19dc6478ab4", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Housing Element", "Goal HOU-1.", "Objective HOU-1.6.", "Policy HOU-1.6.1."], "block_type": "paragraph", "block_index": 656, "text": "The provision of reasonably located standard housing for persons experiencing displacement due to public actions shall be supported, where appropriate.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b657__c0__43f3169ff7a7", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Housing Element", "Goal HOU-1.", "Objective HOU-1.7."], "block_type": "heading", "block_index": 657, "text": "Objective HOU-1.7.", "extra": {"heading_level": 4, "style": "Heading 4"}}
{"id": "Coral_Gables_Comprehensive_Plan__b658__c0__cae77d533ff0", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Housing Element", "Goal HOU-1.", "Objective HOU-1.7."], "block_type": "paragraph", "block_index": 658, "text": "As provided herein, the City shall continue to address future affordable/ attainable housing needs pursuant to the Workforce/Affordable Housing Study for the City of Coral Gables (revised 2017) referenced as an Appendix. Future findings and recommendation shall be based upon this established data and analysis contained within the Study and necessary amendments or updates to the Study.", "extra": {"style": "Body Text"}}
