{"id": "Coral_Gables_Comprehensive_Plan__b670__c0__540b3e9b8657", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Education Element", "Goal EDU-1."], "block_type": "heading", "block_index": 670, "text": "Goal EDU-1.", "extra": {"heading_level": 3, "style": "Heading 3"}}
{"id": "Coral_Gables_Comprehensive_Plan__b671__c0__29253b04324a", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Education Element", "Goal EDU-1."], "block_type": "paragraph", "block_index": 671, "text": "The City cooperates with Miami-Dade County Public Schools and other appropriate governmental agencies in the development, operation, and maintenance of a system of public education, and strives to improve the quality and quantity of public educational facilities available to the citizens of the City of Coral Gables and Miami-Dade County.", "extra": {"style": "Body Text"}}
