{"id": "Coral_Gables_Comprehensive_Plan__b674__c0__e7fe9dd999f6", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Education Element", "Goal EDU-1.", "Objective EDU-1.1.", "Policy EDU-1.1.1."], "block_type": "heading", "block_index": 674, "text": "Policy EDU-1.1.1.", "extra": {"heading_level": 5, "style": "Heading 5"}}
