{"id": "Coral_Gables_Comprehensive_Plan__b679__c0__8678afe5f34c", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Education Element", "Goal EDU-1.", "Objective EDU-1.1.", "Policy EDU-1.1.3."], "block_type": "paragraph", "block_index": 679, "text": "Coordinate with Miami-Dade County Public Schools in their efforts to develop and implement alternative educational facilities, such as primary learning centers, which can be constructed on small parcels of land and relieve overcrowding at elementary schools, in so far as funding and rules permit.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b680__c0__fa49d6dbb62f", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Education Element", "Goal EDU-1.", "Objective EDU-1.1.", "Policy EDU-1.1.4."], "block_type": "heading", "block_index": 680, "text": "Policy EDU-1.1.4.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"id": "Coral_Gables_Comprehensive_Plan__b681__c0__799ab8cbf9a4", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Education Element", "Goal EDU-1.", "Objective EDU-1.1.", "Policy EDU-1.1.4."], "block_type": "paragraph", "block_index": 681, "text": "Coordinate with Miami-Dade County Public Schools in their efforts to provide public school facilities to the students of Miami-Dade County, which operate at optimum capacity, in so far as funding is available. Operational alternatives may be developed and implemented, where appropriate, which mitigate the impacts of overcrowding while maintaining the instructional integrity of the educational program.", "extra": {"style": "Body Text"}}
