{"id": "Coral_Gables_Comprehensive_Plan__b714__c0__ac7ff5d475c2", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Education Element", "Goal EDU-1.", "Objective EDU-1.3.", "Policy EDU-1.3.1."], "block_type": "paragraph", "block_index": 714, "text": "Where possible, Miami-Dade County Public Schools should seek sites for future educational facility development which are adjacent to existing or planned public recreation areas, community centers, libraries, or other compatible civic uses for the purpose of encouraging joint use facilities or the creation of logical focal points for community activity.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b715__c0__33ed3123baea", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Education Element", "Goal EDU-1.", "Objective EDU-1.3.", "Policy EDU-1.3.2."], "block_type": "heading", "block_index": 715, "text": "Policy EDU-1.3.2.", "extra": {"heading_level": 5, "style": "Heading 5"}}
