{"id": "Coral_Gables_Comprehensive_Plan__b718__c0__26f13986bf74", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Education Element", "Goal EDU-1.", "Objective EDU-1.3.", "Policy EDU-1.3.3."], "block_type": "paragraph", "block_index": 718, "text": "When considering a site for possible use as an educational facility, Miami-Dade County Public Schools will review the adequacy and proximity of other public facilities and services necessary to the site such as roadway access, transportation, fire flow and portable water, sanitary sewers, drainage, solid waste, police and fire services, and means by which to assure safe access to schools, including sidewalks, bicycle paths, turn lanes, and signalization.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b719__c0__6713e5228fd9", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Education Element", "Goal EDU-1.", "Objective EDU-1.3.", "Policy EDU-1.3.4."], "block_type": "heading", "block_index": 719, "text": "Policy EDU-1.3.4.", "extra": {"heading_level": 5, "style": "Heading 5"}}
