{"id": "Coral_Gables_Comprehensive_Plan__b854__c0__59ce8ef81412", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Mobility Element", "Goal MOB-2.", "Objective MOB-2.2."], "block_type": "heading", "block_index": 854, "text": "Objective MOB-2.2.", "extra": {"heading_level": 4, "style": "Heading 4"}}
{"id": "Coral_Gables_Comprehensive_Plan__b855__c0__e5cdb48086dd", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Mobility Element", "Goal MOB-2.", "Objective MOB-2.2."], "block_type": "paragraph", "block_index": 855, "text": "The City shall maintain and continue to monitor its Transportation Concurrency Exception Area (TCEA) within the City's Concurrency Management Program pursuant to the policies listed below.", "extra": {"style": "Body Text"}}
