{"id": "Coral_Gables_Comprehensive_Plan__b859__c0__6e717c24de68", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Mobility Element", "Goal MOB-2.", "Objective MOB-2.2.", "Policy MOB-2.2.2."], "block_type": "heading", "block_index": 859, "text": "Policy MOB-2.2.2.", "extra": {"heading_level": 5, "style": "Heading 5"}}
