{"id": "Coral_Gables_Comprehensive_Plan__b918__c0__84efbf4825f5", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Mobility Element", "Goal MOB-2.", "Objective MOB-2.7.", "Policy MOB-2.7.1."], "block_type": "paragraph", "block_index": 918, "text": "The City shall, via the review of development projects and city transportation improvement projects, conserve and protect the character and livability of all residential neighborhoods by preventing the intrusion of through vehicles on local and collector streets. The City shall discourage through traffic in neighborhoods and may incorporate traffic management and calming measures including, but not limited to, signage, landscape design, traffic calming devices and roadway design.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b919__c0__8d21d295ddcd", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Mobility Element", "Goal MOB-2.", "Objective MOB-2.7.", "Policy MOB-2.7.2."], "block_type": "heading", "block_index": 919, "text": "Policy MOB-2.7.2.", "extra": {"heading_level": 5, "style": "Heading 5"}}
