{"id": "Coral_Gables_Comprehensive_Plan__b936__c0__a68f673feb20", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Mobility Element", "Goal MOB-2.", "Objective MOB-2.8.", "Policy MOB-2.8.4."], "block_type": "heading", "block_index": 936, "text": "Policy MOB-2.8.4.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"id": "Coral_Gables_Comprehensive_Plan__b937__c0__d70ad1de9933", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Mobility Element", "Goal MOB-2.", "Objective MOB-2.8.", "Policy MOB-2.8.4."], "block_type": "paragraph", "block_index": 937, "text": "If no feasible alternative exists, needed transportation facilities may be placed in environmentally protected conservation areas. However, such areas are to be limited and design techniques used to minimize the negative impact upon the natural systems to the greatest extent possible.", "extra": {"style": "Body Text"}}
