{"id": "Coral_Gables_Comprehensive_Plan__b997__c0__d954a8eff974", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Natural Resources Element", "Goal NAT-1.", "Objective NAT-1.2.", "Policy NAT-1.2.11."], "block_type": "heading", "block_index": 997, "text": "Policy NAT-1.2.11.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"id": "Coral_Gables_Comprehensive_Plan__b998__c0__957575e8e617", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Natural Resources Element", "Goal NAT-1.", "Objective NAT-1.2.", "Policy NAT-1.2.11."], "block_type": "paragraph", "block_index": 998, "text": "The City will educate the development community on the water saving benefits of the use of sub-metering for all multi-unit residential development which will include: separate meter and monthly records kept of all major water-using functions such as cooling towers and individual buildings in all new and redeveloped multi-family residential projects.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b999__c0__c282eb746aec", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Natural Resources Element", "Goal NAT-1.", "Objective NAT-1.2.", "Policy NAT-1.2.12."], "block_type": "heading", "block_index": 999, "text": "Policy NAT-1.2.12.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1000__c0__501e53dfc5da", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Natural Resources Element", "Goal NAT-1.", "Objective NAT-1.2.", "Policy NAT-1.2.12."], "block_type": "paragraph", "block_index": 1000, "text": "The City will educate the development community on the water saving benefits of the use of Florida Friendly Landscapes guidelines and principles. The City will encourage through the use of educational materials, the use of the following techniques: rain harvesting through the use of rain barrels and directing runoff to landscaped areas; drip irrigation or micro-sprinklers; and the use of porous surface materials (bricks, gravel, turf block, mulch, pervious concrete, etc) on walkways, driveways and patios.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1001__c0__b57d89d27846", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Natural Resources Element", "Goal NAT-1.", "Objective NAT-1.2.", "Policy NAT-1.2.13."], "block_type": "heading", "block_index": 1001, "text": "Policy NAT-1.2.13.", "extra": {"heading_level": 5, "style": "Heading 5"}}
