{"id": "Coral_Gables_Comprehensive_Plan__b1044__c0__4c1c22c78544", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Natural Resources Element", "Goal NAT-1.", "Objective NAT-1.6.", "Policy NAT-1.6.5."], "block_type": "paragraph", "block_index": 1044, "text": "Explore strategies for promoting environmentally sensitive development, such as the U.S. Green Building Council’s “Leadership in Energy and Environmental Design (LEED)” certification.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1045__c0__111f161975c5", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Natural Resources Element", "Goal NAT-1.", "Objective NAT-1.7."], "block_type": "heading", "block_index": 1045, "text": "Objective NAT-1.7.", "extra": {"heading_level": 4, "style": "Heading 4"}}
