{"id": "Coral_Gables_Comprehensive_Plan__b1052__c0__d7b6cfab90d2", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Natural Resources Element", "Goal NAT-2.", "Objective NAT-2.1."], "block_type": "paragraph", "block_index": 1052, "text": "Maintain or improve coastal area and estuarine environmental quality, as measured by existing baseline environmental indicators for water quality provided by Miami-Dade Department of Environmental Regulation and Management. This objective shall be achieved through the implementation of the following policies.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1053__c0__a3a82c8dc896", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Natural Resources Element", "Goal NAT-2.", "Objective NAT-2.1.", "Policy NAT-2.1.1."], "block_type": "heading", "block_index": 1053, "text": "Policy NAT-2.1.1.", "extra": {"heading_level": 5, "style": "Heading 5"}}
