{"id": "Coral_Gables_Comprehensive_Plan__b1058__c0__8d5275090af0", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Natural Resources Element", "Goal NAT-2.", "Objective NAT-2.1.", "Policy NAT-2.1.3."], "block_type": "paragraph", "block_index": 1058, "text": "The City shall cooperate with the South Florida Water Management District, state agencies, and local government jurisdictions for areawide water resources planning and management.", "extra": {"style": "Body Text"}}
