{"id": "Coral_Gables_Comprehensive_Plan__b1063__c0__d617db068cea", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Natural Resources Element", "Goal NAT-2.", "Objective NAT-2.2."], "block_type": "heading", "block_index": 1063, "text": "Objective NAT-2.2.", "extra": {"heading_level": 4, "style": "Heading 4"}}
