{"id": "Coral_Gables_Comprehensive_Plan__b1071__c0__4d44636293ac", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Natural Resources Element", "Goal NAT-2.", "Objective NAT-2.2.", "Policy NAT-2.2.4."], "block_type": "heading", "block_index": 1071, "text": "Policy NAT-2.2.4.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1072__c0__7b4cfa7031e9", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Natural Resources Element", "Goal NAT-2.", "Objective NAT-2.2.", "Policy NAT-2.2.4."], "block_type": "paragraph", "block_index": 1072, "text": "The City shall maintain its canals and waterways, with specific attention to maintenance dredging and spoil disposition activities to enhance existing water quality. Maintenance shall result in minimal disruption of natural habitat. Discharge of pollutants and disposal of wastes into canals, storm drains, submerged lands, or open waters is prohibited. The City hereby incorporates by reference the Emergency Operation Plan and the direction provided in the hazard mitigation annex of the Operations Plan.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1073__c0__d4461f686f15", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Natural Resources Element", "Goal NAT-2.", "Objective NAT-2.2.", "Policy NAT-2.2.5."], "block_type": "heading", "block_index": 1073, "text": "Policy NAT-2.2.5.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1074__c0__f7b82cc34193", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Natural Resources Element", "Goal NAT-2.", "Objective NAT-2.2.", "Policy NAT-2.2.5."], "block_type": "paragraph", "block_index": 1074, "text": "Historic sites shall be identified and protected, and performance standards for development and sensitive reuse for historic resources shall be established.", "extra": {"style": "Body Text"}}
