{"id": "Coral_Gables_Comprehensive_Plan__b1075__c0__4547d254467c", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Natural Resources Element", "Goal NAT-2.", "Objective NAT-2.3."], "block_type": "heading", "block_index": 1075, "text": "Objective NAT-2.3.", "extra": {"heading_level": 4, "style": "Heading 4"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1076__c0__047e89d1d430", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Natural Resources Element", "Goal NAT-2.", "Objective NAT-2.3."], "block_type": "paragraph", "block_index": 1076, "text": "Restore and enhance disturbed or degraded natural resources and implement programs to mitigate future natural resources disruption or degradation in the coastal area. This objective shall be achieved through the implementation of the following policies.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1077__c0__3244e1d438df", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Natural Resources Element", "Goal NAT-2.", "Objective NAT-2.3.", "Policy NAT-2.3.1."], "block_type": "heading", "block_index": 1077, "text": "Policy NAT-2.3.1.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1078__c0__1003a4828d8a", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Natural Resources Element", "Goal NAT-2.", "Objective NAT-2.3.", "Policy NAT-2.3.1."], "block_type": "paragraph", "block_index": 1078, "text": "Existing coastal wetlands and submerged lands should not be drained or filled, and should be restored or enhanced where disturbed or degraded by development. The City shall monitor dredge and fill permits issued by the U.S. Army Corps of Engineers and shall further monitor new development applications to the City to ensure that this policy is enforced.", "extra": {"style": "Body Text"}}
