{"id": "Coral_Gables_Comprehensive_Plan__b1099__c0__e05c3984da97", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Recreation and Open Space Element"], "block_type": "paragraph", "block_index": 1099, "text": "Vision Statement: Provide and maintain a high quality and environmentally sensitive system of parks, recreational facilities, and open spaces which create community through memorable experiences.", "extra": {"style": "Body Text"}}
