{"id": "Coral_Gables_Comprehensive_Plan__b1171__c0__16ce40a71efe", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Recreation and Open Space Element", "Goal REC-1.", "Objective REC-1.4.", "Policy REC-1.4.4."], "block_type": "paragraph", "block_index": 1171, "text": "The City shall continue to follow established policy and procedure to prohibit encroachment of City parks, facilities and open spaces. The policy identifies proper procedures for defense against encroachment.", "extra": {"style": "Body Text"}}
