"], "block_type": "heading", "block_index": 1187, "text": "Goal HIS-1.", "extra": {"heading_level": 3, "style": "Heading 3"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1188__c0__b5514f902af7", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Historical Resources Element", "Goal HIS-1."], "block_type": "paragraph", "block_index": 1188, "text": "Preserve and promote the recognition of structures, sites, manmade or natural landscape elements, works of art or integrated combinations thereof, which serve as visible reminders of the history and cultural heritage of the City.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1189__c0__9894b1d9418d", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Historical Resources Element", "Goal HIS-1.", "Objective HIS-1.1."], "block_type": "heading", "block_index": 1189, "text": "Objective HIS-1.1.", "extra": {"heading_level": 4, "style": "Heading 4"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1190__c0__923e2c93e62f", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Historical Resources Element", "Goal HIS-1.", "Objective HIS-1.1."], "block_type": "paragraph", "block_index": 1190, "text": "Increase the number of documented historic resources within the City of Coral Gables for the purpose of recognition and planning for their protection and preservation. As of December 2008, over 1,000 buildings, structures, objects and formal landscape features are listed on the Coral Gables Register of Historic Places, either as individual local landmarks or as sites within the City’s established 21 local historic districts (see HIS-1: Historic Landmark Districts Map).", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1191__c0__427f10c33e72", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Historical Resources Element", "Goal HIS-1.", "Objective HIS-1.1.", "Policy HIS-1.1.1."], "block_type": "heading", "block_index": 1191, "text": "Policy HIS-1.1.1.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1192__c0__9224b48f992b", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Historical Resources Element", "Goal HIS-1.", "Objective HIS-1.1.", "Policy HIS-1.1.1."], "block_type": "paragraph", "block_index": 1192, "text": "The City shall continue to identify, and increase the number of locally designated historic landmarks on the Coral Gables Register of Historic Places at an average rate of one per month.", "extra": {"style": "Body Text"}}
