{"id": "Coral_Gables_Comprehensive_Plan__b1255__c0__e068a1f6ec61", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Historical Resources Element", "Goal HIS-5.", "Objective HIS-5.1.", "Policy HIS-5.1.2."], "block_type": "paragraph", "block_index": 1255, "text": "The City shall continue its current use and documentation of Transfer of Development Rights (TDRs) to provide for the preservation and protection of historic landmarks, properties or areas. The City shall examine the possible expansion of the TDR district or creation of other TDR districts and possible amendments to the program to provide for additional incentives to promote historic and cultural preservation.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1256__c0__a8cae4e10c84", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Historical Resources Element", "Goal HIS-5.", "Objective HIS-5.1.", "Policy HIS-5.1.3."], "block_type": "heading", "block_index": 1256, "text": "Policy HIS-5.1.3.", "extra": {"heading_level": 5, "style": "Heading 5"}}
