{"id": "Coral_Gables_Comprehensive_Plan__b1290__c0__592757222308", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Public Safety Element", "Goal SAF-1.", "Objective SAF-1.4."], "block_type": "paragraph", "block_index": 1290, "text": "The City shall seek to reduce the exposure of life and property to hurricanes and other disasters through the planning and implementation of emergency preparedness, response and recovery plans.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1291__c0__285123f7593b", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Public Safety Element", "Goal SAF-1.", "Objective SAF-1.4.", "Policy SAF-1.4.1."], "block_type": "heading", "block_index": 1291, "text": "Policy SAF-1.4.1.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1292__c0__8f60f45eaa7a", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Public Safety Element", "Goal SAF-1.", "Objective SAF-1.4.", "Policy SAF-1.4.1."], "block_type": "paragraph", "block_index": 1292, "text": "Develop an emergency preparedness, response and recovery plan and update it every two years to provide comprehensive pre-disaster planning consistent with Miami-Dade County’s Emergency Management Plan.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1293__c0__7afa48900a1f", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Public Safety Element", "Goal SAF-1.", "Objective SAF-1.4.", "Policy SAF-1.4.2."], "block_type": "heading", "block_index": 1293, "text": "Policy SAF-1.4.2.

"], "block_type": "paragraph", "block_index": 1292, "text": "Develop an emergency preparedness, response and recovery plan and update it every two years to provide comprehensive pre-disaster planning consistent with Miami-Dade County’s Emergency Management Plan.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1293__c0__7afa48900a1f", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Public Safety Element", "Goal SAF-1.", "Objective SAF-1.4.", "Policy SAF-1.4.2."], "block_type": "heading", "block_index": 1293, "text": "Policy SAF-1.4.2.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1294__c0__1c455f524e13", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Public Safety Element", "Goal SAF-1.", "Objective SAF-1.4.", "Policy SAF-1.4.2."], "block_type": "paragraph", "block_index": 1294, "text": "Due to the City’s location within the Coastal High Hazard Area and general vulnerability to hurricane events, the City shall implement and/or adhere to emergency management and hurricane evacuation plans and procedures through land use controls.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1295__c0__df41092017de", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Public Safety Element", "Goal SAF-1.", "Objective SAF-1.4.", "Policy SAF-1.4.3."], "block_type": "heading", "block_index": 1295, "text": "Policy SAF-1.4.3.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1296__c0__e868837f60a1", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Public Safety Element", "Goal SAF-1.", "Objective SAF-1.4.", "Policy SAF-1.4.3."], "block_type": "paragraph", "block_index": 1296, "text": "The City shall coordinate with adjacent municipalities, Miami-Dade County, the Florida Department of Transportation and other agencies, as appropriate, to ensure the ability of the regional transportation network to provide for the safe and timely evacuation of residents in a hurricane or other emergency event.", "extra": {"style": "Body Text"}}
