{"id": "Coral_Gables_Comprehensive_Plan__b1302__c0__e86b5b9c4211", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Public Safety Element", "Goal SAF-2."], "block_type": "paragraph", "block_index": 1302, "text": "Protect human life and investment in the coastal area of the City.", "extra": {"style": "Body Text"}}
