{"id": "Coral_Gables_Comprehensive_Plan__b1304__c0__12ae3b621756", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Public Safety Element", "Goal SAF-2.

", "Objective SAF-2.1."], "block_type": "heading", "block_index": 1303, "text": "Objective SAF-2.1.", "extra": {"heading_level": 4, "style": "Heading 4"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1304__c0__12ae3b621756", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Public Safety Element", "Goal SAF-2.", "Objective SAF-2.1."], "block_type": "paragraph", "block_index": 1304, "text": "Limit public expenditures in coastal areas to projects clearly in the public interest and which minimize the risk from storm damage. This objective shall be achieved through the implementation of the following policies.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1305__c0__39dcbff04217", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Public Safety Element", "Goal SAF-2.", "Objective SAF-2.1.", "Policy SAF-2.1.1."], "block_type": "heading", "block_index": 1305, "text": "Policy SAF-2.1.1.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1306__c0__b85b964da237", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Public Safety Element", "Goal SAF-2.", "Objective SAF-2.1.", "Policy SAF-2.1.1."], "block_type": "paragraph", "block_index": 1306, "text": "Public expenditures for infrastructure improvements shall be located outside flood prone areas, to the extent practicable, to keep floodways as unobstructed as possible.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1307__c0__46e7b8667b5e", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Public Safety Element", "Goal SAF-2.", "Objective SAF-2.1.", "Policy SAF-2.1.2."], "block_type": "heading", "block_index": 1307, "text": "Policy SAF-2.1.2.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1308__c0__b38c6918f9b3", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Public Safety Element", "Goal SAF-2.", "Objective SAF-2.1.", "Policy SAF-2.1.2."], "block_type": "paragraph", "block_index": 1308, "text": "Limit public expenditures that subsidize development permitted in coastal areas as defined herein except for restoration or enhancement of natural resources.", "extra": {"style": "Body Text"}}
