{"id": "Coral_Gables_Comprehensive_Plan__b1369__c0__1c000578c4ef", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.1.", "Policy CIE-1.1.2."], "block_type": "paragraph", "block_index": 1369, "text": "The Five (5) Year Schedule of Improvements contained in the CIE shall include capital projects for renovation, replacement, upgrading, and new facilities as necessary to maintain the adopted level of service standards, balanced to meet local needs and abilities.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1370__c0__3f9584429312", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.1.", "Policy CIE-1.1.3."], "block_type": "heading", "block_index": 1370, "text": "Policy CIE-1.1.3.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1371__c0__29eb91c063ba", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.1.", "Policy CIE-1.1.3."], "block_type": "paragraph", "block_index": 1371, "text": "The City shall adopt an annual capital budget which contains the projects from the Five (5) Year Schedule of Improvements for the specified year.", "extra": {"style": "Body Text"}}
