{"id": "Coral_Gables_Comprehensive_Plan__b1373__c0__6c52acd8c23b", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.1.", "Policy CIE-1.1.4."], "block_type": "paragraph", "block_index": 1373, "text": "The City manages its long term general obligation debt in a manner that ensures that the ratio of the debt service millage to the citywide millage does not exceed twenty (20%) percent.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1374__c0__867c4c4f854a", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.1.", "Policy CIE-1.1.5."], "block_type": "heading", "block_index": 1374, "text": "Policy CIE-1.1.5.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1375__c0__3e16a6cccdad", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.1.", "Policy CIE-1.1.5."], "block_type": "paragraph", "block_index": 1375, "text": "The City shall incorporate capital improvements affecting City LOS for water supply by referencing the Capital Improvements Schedules of Miami-Dade County, state agencies, regional water supply authorities and other units of government providing services but not having regulatory authority over the use of land via reference during periodic updates of the Comprehensive Plan.", "extra": {"style": "Body Text"}}
