{"id": "Coral_Gables_Comprehensive_Plan__b1459__c0__f2d8a4163059", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.5.", "Policy CIE-1.5.1."], "block_type": "heading", "block_index": 1459, "text": "Policy CIE-1.5.1.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1460__c0__e7b5e40edc3d", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.5.", "Policy CIE-1.5.1."], "block_type": "paragraph", "block_index": 1460, "text": "The City shall be limited on the use of revenue bonds to no more than twenty-five (25%) percent total debt. The total debt service shall not exceed six (6%) percent of total revenue; and outstanding capital indebtedness shall not exceed eight (8%) percent of the total property tax base of the City.", "extra": {"style": "Body Text"}}
