{"id": "Coral_Gables_Comprehensive_Plan__b1461__c0__e18e6b463447", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.6."], "block_type": "heading", "block_index": 1461, "text": "Objective CIE-1.6.", "extra": {"heading_level": 4, "style": "Heading 4"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1462__c0__c9b7ba029f28", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.6."], "block_type": "paragraph", "block_index": 1462, "text": "The City shall ensure the provision of public facilities and services at no less than the established LOS standards and manage the land development process to assure public facility needs do not exceed the City's ability to adequately fund and provide or require provision of needed capital improvements. The City will use the collection of impact fees to adequately fund services and projects related to roadways, parks, police, fire and general government services.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1463__c0__f5fdcb524828", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.6.", "Policy CIE-1.6.1."], "block_type": "heading", "block_index": 1463, "text": "Policy CIE-1.6.1.", "extra": {"heading_level": 5, "style": "Heading 5"}}
