{"id": "Coral_Gables_Comprehensive_Plan__b1472__c0__4afcb53919ef", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-1.", "Objective CIE-1.6.", "Policy CIE-1.6.5."], "block_type": "paragraph", "block_index": 1472, "text": "The City shall conduct a complete review of the Impact Fee program every three years to determine if changes in costs, facility needs, development patterns, demographics and any other relevant factors indicate a need to update the impact fees.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1473__c0__d83701b1aa05", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-2."], "block_type": "heading", "block_index": 1473, "text": "Goal CIE-2.", "extra": {"heading_level": 3, "style": "Heading 3"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1474__c0__9592a719560d", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Capital Improvements Element", "Goal CIE-2."], "block_type": "paragraph", "block_index": 1474, "text": "The City maintains a 5-Year Capital Improvement Program (CIP) containing projects that are financially feasible and necessary due to deficiencies in levels of service identified in other Comprehensive Plan elements or are other capital improvements which the City has determined shall be included in its CIP in provision of public services at or above the minimum LOS standards as adopted.", "extra": {"style": "Body Text"}}
