{"id": "Coral_Gables_Comprehensive_Plan__b1667__c0__7120d86143a7", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Coastal Management Element", "Goal CMT-1.", "Objective CMT-1.1."], "block_type": "paragraph", "block_index": 1667, "text": "Preserve and restore existing natural systems resources including wetlands and mangrove systems within Matheson Hammock Park, Chapman Field Park, R. Hardy Matheson Preserve, and the Cocoplum mangrove preserve, as well as those portions of Biscayne Bay that lie within the City's boundaries.", "extra": {"style": "Body Text"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1668__c0__4181f96dad64", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Coastal Management Element", "Goal CMT-1.", "Objective CMT-1.1.", "Policy CMT-1.1.1."], "block_type": "heading", "block_index": 1668, "text": "Policy CMT-1.1.1.", "extra": {"heading_level": 5, "style": "Heading 5"}}
{"id": "Coral_Gables_Comprehensive_Plan__b1669__c0__f9a87bca7200", "doc_id": "Coral_Gables_Comprehensive_Plan", "source_path": "/workspaces/civicai-mvp/data/raw/Coral_Gables_Comprehensive_Plan.docx", "section_path": ["Administration Element", "Coastal Management Element", "Goal CMT-1.", "Objective CMT-1.1.", "Policy CMT-1.1.1."], "block_type": "paragraph", "block_index": 1669, "text": "The City will adhere to Miami-Dade County Regulatory and Economic Resources Department – Division of Environmental Resources Management (RER-DERM) standards and require RER-DERM approvals in its permitting procedures to ensure that facilities in the Coastal Zone as defined in Chapter 380.205(2) F.S. and near major canals do not pose a significant threat to water quality or diminish the quality or extent of the natural environment.", "extra": {"style": "Body Text"}}
